def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Determine starting point
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent
            if current == '':
                current = ''
            else:
                # Remove last component
                parts = current.rstrip('/').split('/')
                if len(parts) > 1:
                    current = '/'.join(parts[:-1])
                else:
                    current = ''
            i += 1
            continue

        # Append the component to current path
        if current == '':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the symlink target
            target = links[current]

            # Determine the directory containing the link
            if current == '':
                link_dir = ''
            else:
                parts = current.rstrip('/').split('/')
                if len(parts) > 1:
                    link_dir = '/'.join(parts[:-1])
                else:
                    link_dir = ''

            # Resolve the target relative to the link's directory
            if target.startswith('/'):
                # Absolute target
                current = ''
                target_components = target.split('/')
            else:
                # Relative target
                current = link_dir
                target_components = target.split('/')

            # Process remaining target components and original path components
            components = target_components + components[i+1:]
            i = 0
            continue

        i += 1

    # Return the result
    if current == '':
        return '/'
    else:
        return current

